//! Standalone binary for generating TypeScript bindings.
//!
//! Run with: `cargo run --bin export-bindings`
//! Output: `../src/shared/types/bindings.ts`

fn main() {
    use specta_typescript::Typescript;

    let builder = axelate_lib::create_specta_builder();
    builder
        .export(
            Typescript::default().header(
                "/* eslint-disable */\n\
                 // @ts-nocheck\n\
                 // This file was generated by [tauri-specta](https://github.com/oscartbeaumont/tauri-specta).\n\
                 // Do not edit this file manually, as it will be overwritten.\n",
            ),
            "../src/shared/types/bindings.ts",
        )
        .expect("Failed to export TypeScript bindings");

    println!("✅ TypeScript bindings exported to src/shared/types/bindings.ts");
}
